def power(base, exp=2):
    return base ** exp

print(power(3), power(2, 5), power(exp=3, base=2))

def total(*nums):
    return sum(nums)

print(total(1, 2, 3), total())

def info(**options):
    for key, value in options.items():
        print(key, "=", value)

info(color="red", size=3)

def point(x, y, z=0):
    return (x, y, z)

coords = [1, 2]
print(point(*coords), point(*coords, **{"z": 5}))

def connect(host, *, timeout=5):
    return f"{host}:{timeout}"

print(connect("db", timeout=10))

def add(item, items=None):
    if items is None:
        items = []
    items.append(item)
    return items

print(add("a"), add("b"))

def multiplier(k):
    def mul(x):
        return x * k
    return mul

triple = multiplier(3)
print(triple(5), multiplier(10)(4))

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

print(factorial(5))

def flatten(items):
    result = []
    for x in items:
        if isinstance(x, list):
            result.extend(flatten(x))
        else:
            result.append(x)
    return result

print(flatten([1, [2, [3, 4]], 5]))

memo = {}

def fib(n):
    if n < 2:
        return n
    if n not in memo:
        memo[n] = fib(n - 1) + fib(n - 2)
    return memo[n]

print(fib(80))

from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

print(fib(90))

