        print("другое:", type(e).__name__)

class InsufficientFunds(Exception):
    pass

def withdraw(balance, amount):
    if amount > balance:
        raise InsufficientFunds(f"не хватает {amount - balance}")
    return balance - amount

try:
    withdraw(50, 80)
except InsufficientFunds as e:
    print("Ошибка:", e)

