        self.name = name

    def bark(self):
        return f"{self.name}: Гав!"

a = Dog("Рекс")
b = Dog("Шарик")
print(a.bark(), b.bark())

class Person:
    def __init__(self, name):
        self.name = name

class Student(Person):
    def __init__(self, name, group):
        super().__init__(name)
        self.group = group

s = Student("Ада", "П-1")
print(s.name, s.group)

