    def sound(self):
        return "кря"

class Robot:
    def sound(self):
        return "бип"

for x in [Duck(), Robot()]:
    print(x.sound())

class A:
    def who(self):
        return "A"

class B(A):
    def who(self):
        return "B" + super().who()

class C(A):
    def who(self):
        return "C" + super().who()

class D(B, C):
    def who(self):
        return "D" + super().who()

print(D().who(), B().who(), [k.__name__ for k in D.__mro__])

from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self): ...

class Square(Shape):
    def __init__(self, a):
        self.a = a
    def area(self):
        return self.a ** 2

print(Square(3).area())
try:
    Shape()
except TypeError:
    print("абстрактный класс создать нельзя")

class Money:
    def __init__(self, amount):
        self.amount = amount
    def __str__(self):
        return f"{self.amount} ₽"
    def __repr__(self):
        return f"Money({self.amount})"

m = Money(5)
print(m, [m], f"{m!r}")

class Vec:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __add__(self, other):
        return Vec(self.x + other.x, self.y + other.y)
    def __eq__(self, other):
        if not isinstance(other, Vec):
            return NotImplemented
        return (self.x, self.y) == (other.x, other.y)
    def __hash__(self):
        return hash((self.x, self.y))
    def __repr__(self):
        return f"Vec({self.x}, {self.y})"

print(Vec(1, 2) + Vec(3, 4), Vec(1, 1) == Vec(1, 1), len({Vec(1, 1), Vec(1, 1)}), Vec(1, 1) == 5)

class Playlist:
    def __init__(self):
        self.songs = ["intro", "verse", "outro"]
    def __len__(self):
        return len(self.songs)
    def __getitem__(self, i):
        return self.songs[i]

p = Playlist()
print(len(p), p[0], "verse" in p, p[1:], list(reversed(p)))

class Temp:
    def __init__(self, c):
        self.c = c

    @property
    def c(self):
        return self._c

    @c.setter
    def c(self, value):
        if value < -273.15:
            raise ValueError("ниже абсолютного нуля")
        self._c = value

    @property
    def f(self):
        return self.c * 9 / 5 + 32

t = Temp(25)
print(t.c, t.f)
try:
    t.c = -300
except ValueError as e:
    print(e)

class Temperature:
    def __init__(self, celsius):
        self.celsius = celsius

    @classmethod
    def from_fahrenheit(cls, f):
        return cls(round((f - 32) * 5 / 9, 1))

    @staticmethod
    def is_freezing(celsius):
        return celsius <= 0

t = Temperature.from_fahrenheit(212)
print(t.celsius, Temperature.is_freezing(-5), t.is_freezing(t.celsius))

class Safe:
    def __init__(self):
        self.__code = 42

s = Safe()
print(hasattr(s, "__code"), s._Safe__code)

class Pixel:
    __slots__ = ("r", "g", "b")
    def __init__(self, r, g, b):
        self.r, self.g, self.b = r, g, b

p = Pixel(255, 0, 0)
try:
    p.alpha = 1
except AttributeError:
    print("атрибута alpha нет в __slots__")

from functools import wraps

def log(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print("вызов", func.__name__, args)
        return func(*args, **kwargs)
    return wrapper

@log
def add(a, b):
    return a + b

print(add(2, 3), add.__name__)

def repeat(n):
    def deco(func):
        def wrapper(*args):
            return [func(*args) for _ in range(n)]
        return wrapper
    return deco

@repeat(3)
def hello(name):
    return f"привет, {name}"

print(hello("Ада"))

class Tag:
    def __init__(self, name):
        self.name = name
    def __enter__(self):
        print(f"<{self.name}>")
        return self
    def __exit__(self, exc_type, exc, tb):
        print(f"</{self.name}>")

with Tag("div"), Tag("p"):
    print("текст")

from typing import Protocol, runtime_checkable

@runtime_checkable
class Speaker(Protocol):
    def speak(self) -> str: ...

class Dog:
    def speak(self) -> str:
        return "гав"

def talk(s: Speaker) -> str:
    return s.speak()

print(talk(Dog()), isinstance(Dog(), Speaker), isinstance(42, Speaker))

def first[T](items: list[T]) -> T:
    return items[0]

print(first([3, 1]), first(["a", "b"]), first.__type_params__)

prices = {"чай": 3}
print(prices.get("кофе", 0), prices.setdefault("сок", 5), prices)
nums = [3, 7, 10]
print(any(n > 9 for n in nums), all(n > 2 for n in nums))
for i, n in enumerate(nums, 1):
    print(i, n)

def clamp(x, lo, hi):
    return max(lo, min(x, hi))

def test_clamp():
    assert clamp(5, 0, 10) == 5
    assert clamp(-3, 0, 10) == 0, "ниже нижней границы"
    assert clamp(99, 0, 10) == 10

test_clamp()
print("тесты прошли")
